changeSet.sql:
INSERT INTO jhi_authority(name) SELECT 'ROLE_SUPER_ADMIN' WHERE NOT EXISTS (SELECT 1 FROM jhi_authority WHERE name='ROLE_SUPER_ADMIN');
INSERT INTO jhi_authority(name) SELECT 'ROLE_COMMUNITY_MANAGER' WHERE NOT EXISTS (SELECT 1 FROM jhi_authority WHERE name='ROLE_COMMUNITY_MANAGER');
INSERT INTO jhi_authority(name) SELECT 'ROLE_EVENT_MANAGER' WHERE NOT EXISTS (SELECT 1 FROM jhi_authority WHERE name='ROLE_EVENT_MANAGER');
INSERT INTO jhi_authority(name) SELECT 'ROLE_MODERATOR' WHERE NOT EXISTS (SELECT 1 FROM jhi_authority WHERE name='ROLE_MODERATOR');
INSERT INTO jhi_user_authority(user_id, authority_name)
  SELECT u.id, a.name FROM jhi_user u CROSS JOIN jhi_authority a
  WHERE u.login='ademdemirdev' AND a.name IN ('ROLE_USER','ROLE_ADMIN','ROLE_SUPER_ADMIN')
    AND NOT EXISTS (SELECT 1 FROM jhi_user_authority ua WHERE ua.user_id=u.id AND ua.authority_name=a.name);
